/**
 * Static data shipped with the app (ARCHITECTURE.md §4.2): /data/regions/index.json and
 * /data/regions/<region>/places.geojson. These are generated by the data builder from real OSM
 * and recorded research missions; the planner never adds or edits a place.
 */
import type { Feature, FeatureCollection, MultiPolygon, Point, Polygon } from 'geojson';
import type { Place, PlaceCategory, PlaceRole, RecordedMission, RegionIndexEntry, ScenarioSet } from '../domain/types';

const ROLES: readonly PlaceRole[] = ['origin', 'destination', 'research_origin', 'research_destination'];
const CATEGORIES: readonly PlaceCategory[] = [
  'village',
  'hamlet',
  'nursing_home',
  'social_facility',
  'shelter',
  'assembly_point',
  'school',
  'community_hall',
  'temporary_housing',
  'research',
];

function num(v: unknown): number | null {
  return typeof v === 'number' && Number.isFinite(v) ? v : null;
}

function str(v: unknown): string | null {
  return typeof v === 'string' && v.length > 0 ? v : null;
}

export function parseRegionIndex(raw: unknown): RegionIndexEntry[] {
  if (!Array.isArray(raw)) return [];
  const out: RegionIndexEntry[] = [];
  for (const r of raw as Record<string, unknown>[]) {
    const id = str(r.region_id);
    if (!id) continue;
    const name = (r.name ?? {}) as Record<string, unknown>;
    const bbox = Array.isArray(r.bbox) && r.bbox.length === 4 ? (r.bbox as [number, number, number, number]) : null;
    const center = Array.isArray(r.center) && r.center.length === 2 ? (r.center as [number, number]) : null;
    const counts = r.counts as Record<string, unknown> | undefined;
    out.push({
      id,
      nameKo: str(name.ko) ?? id,
      nameEn: str(name.en) ?? id,
      fireYear: num(r.fire_year),
      eventId: str(r.event_id),
      bbox,
      center,
      zoom: num(r.zoom),
      demo: r.demo === true,
      counts: counts
        ? { origins: num(counts.origins) ?? 0, destinations: num(counts.destinations) ?? 0, research: num(counts.research) ?? 0 }
        : null,
    });
  }
  // demo regions first, then the listed order
  return out.map((r, i) => ({ r, i })).sort((a, b) => Number(b.r.demo) - Number(a.r.demo) || a.i - b.i).map((x) => x.r);
}

function parseRecorded(v: unknown): RecordedMission | null {
  if (!v || typeof v !== 'object') return null;
  const r = v as Record<string, unknown>;
  const destinationId = str(r.destination_id);
  const destinationNode = str(r.destination_node);
  const win = r.destination_window;
  if (!destinationId || !destinationNode || !Array.isArray(win) || win.length !== 2) return null;
  const limits = r.limits as Record<string, unknown> | null | undefined;
  const peak = limits ? num(limits.peak_kw_m2) : null;
  const dose = limits ? num(limits.dose_kj_m2) : null;
  return {
    destinationId,
    destinationNode,
    departOffsetS: num(r.depart_offset_s) ?? 0,
    dwellS: num(r.dwell_s) ?? 120,
    destinationWindow: [Number(win[0]), Number(win[1])],
    incurredDoseKjM2: num(r.incurred_dose_kj_m2),
    limits: peak !== null && dose !== null ? { peakKwM2: peak, doseKjM2: dose } : null,
    horizonS: num(r.horizon_s),
  };
}

export function parsePlaces(raw: unknown): Place[] {
  const fc = raw as FeatureCollection<Point, Record<string, unknown>> | null;
  if (!fc || !Array.isArray(fc.features)) return [];
  const out: Place[] = [];
  for (const f of fc.features as Feature<Point, Record<string, unknown>>[]) {
    const p = f.properties ?? {};
    const id = str(p.id);
    const role = p.role as PlaceRole;
    const coords = f.geometry?.coordinates;
    if (!id || !ROLES.includes(role) || !Array.isArray(coords) || coords.length < 2) continue;
    const category = (CATEGORIES.includes(p.category as PlaceCategory) ? p.category : 'village') as PlaceCategory;
    const osm = p.osm as Record<string, unknown> | null | undefined;
    const snap = p.snap as Record<string, unknown> | null | undefined;
    const entry = p.entry as Record<string, unknown> | null | undefined;
    const entryNode = entry ? str(entry.node) : null;
    out.push({
      id,
      role,
      category,
      name: str(p.name),
      nameEn: str(p.name_en),
      lon: Number(coords[0]),
      lat: Number(coords[1]),
      source: str(p.source) ?? '',
      sourceTag: str(p.source_tag) ?? '',
      osm: osm && str(osm.type) && num(osm.id) !== null ? { type: String(osm.type), id: Number(osm.id) } : null,
      snapNode: (snap ? str(snap.node) : null) ?? entryNode,
      snapDistanceM: (snap ? num(snap.distance_m) : null) ?? (entry ? num(entry.distance_m) : null),
      entry:
        entry && entryNode
          ? {
              node: entryNode,
              lon: num(entry.lon) ?? Number(coords[0]),
              lat: num(entry.lat) ?? Number(coords[1]),
              distanceM: num(entry.distance_m) ?? 0,
              withinApiLonlatSnap: entry.within_api_lonlat_snap === true,
            }
          : null,
      checkable: p.checkable !== false,
      vulnerable: p.vulnerable === true,
      scenarioSetId: str(p.scenario_set_id),
      inputTime: str(p.input_time),
      caseId: str(p.case_id),
      recorded: parseRecorded(p.recorded),
    });
  }
  return out;
}

/** Scenario sets that recorded research missions name (used when neither API nor cache is available). */
export function scenarioSetsFromPlaces(places: Place[]): ScenarioSet[] {
  const seen = new Map<string, ScenarioSet>();
  for (const p of places) {
    if (p.role !== 'research_origin' || !p.scenarioSetId || !p.inputTime) continue;
    if (!seen.has(p.scenarioSetId)) {
      seen.set(p.scenarioSetId, {
        id: p.scenarioSetId,
        inputTime: p.inputTime,
        scenarioIds: [],
        horizonS: p.recorded?.horizonS ?? null,
        hazardSha256: null,
        source: 'places',
      });
    }
  }
  return [...seen.values()].sort((a, b) => a.inputTime.localeCompare(b.inputTime));
}

async function getJson(url: string, signal?: AbortSignal): Promise<unknown> {
  const r = await fetch(url, { signal, headers: { Accept: 'application/json' } });
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  return r.json();
}

export async function loadRegionIndex(signal?: AbortSignal): Promise<RegionIndexEntry[]> {
  return parseRegionIndex(await getJson('/data/regions/index.json', signal));
}

/**
 * places.geojson plus, when present, temporary_housing.geojson (행정안전부 임시주거시설, extra
 * candidate destinations labelled "임시주거시설", never "대피소").
 */
export async function loadPlaces(regionId: string, signal?: AbortSignal): Promise<Place[]> {
  const base = `/data/regions/${encodeURIComponent(regionId)}`;
  const places = parsePlaces(await getJson(`${base}/places.geojson`, signal));
  let extra: Place[] = [];
  try {
    const r = await fetch(`${base}/temporary_housing.geojson`, { signal, headers: { Accept: 'application/geo+json, application/json' } });
    if (r.ok && !(r.headers.get('content-type') ?? '').includes('text/html')) extra = parsePlaces(await r.json());
  } catch {
    extra = [];
  }
  const seen = new Set(places.map((p) => p.id));
  return [...places, ...extra.filter((p) => !seen.has(p.id) && p.role === 'destination')];
}

/** Places that are origins in the selected recorded scenario (OSM origins + its research origins). */
export function scenarioOrigins(places: Place[], scenarioSetId: string | null): Place[] {
  return places.filter(
    (p) => p.role === 'origin' || (p.role === 'research_origin' && scenarioSetId !== null && p.scenarioSetId === scenarioSetId),
  );
}

/** Destinations of the selected scenario (OSM shelters + destinations of its research missions). */
export function scenarioDestinations(places: Place[], scenarioSetId: string | null): Place[] {
  return places.filter(
    (p) => p.role === 'destination' || (p.role === 'research_destination' && scenarioSetId !== null && p.scenarioSetId === scenarioSetId),
  );
}

/**
 * Recorded burned footprint of the parent event at one recorded input time
 * (public/data/regions/<region>/footprints.geojson, ARCHITECTURE.md §4.2). Real data, used only as a
 * starting point (preset) for user-drawn spread zones and labelled as a copy.
 */
export interface Footprint {
  inputTime: string;
  areaKm2: number | null;
  cells: number | null;
  geometry: Polygon | MultiPolygon;
  /** true when the time is also a recorded scenario input time of this region */
  regionScenarioInputTime: boolean;
  source: string | null;
  sourceSha256: string | null;
}

export function parseFootprints(raw: unknown): Footprint[] {
  const fc = raw as FeatureCollection | null;
  if (!fc || !Array.isArray(fc.features)) return [];
  const out: Footprint[] = [];
  for (const f of fc.features) {
    const p = (f.properties ?? {}) as Record<string, unknown>;
    const g = f.geometry;
    const inputTime = str(p.input_time);
    if (!inputTime || !g || (g.type !== 'Polygon' && g.type !== 'MultiPolygon')) continue;
    out.push({
      inputTime,
      areaKm2: num(p.area_km2),
      cells: num(p.cells),
      geometry: g,
      regionScenarioInputTime: p.region_scenario_input_time === true,
      source: str(p.source),
      sourceSha256: str(p.source_sha256),
    });
  }
  return out.sort((a, b) => a.inputTime.localeCompare(b.inputTime));
}

/** footprints.geojson of a region; a missing file means "no presets" (never an error to the user). */
export async function loadFootprints(regionId: string, signal?: AbortSignal): Promise<Footprint[]> {
  const r = await fetch(`/data/regions/${encodeURIComponent(regionId)}/footprints.geojson`, { signal, headers: { Accept: 'application/geo+json, application/json' } });
  if (r.status === 404) return [];
  if (!r.ok) throw new Error(`footprints.geojson: HTTP ${r.status}`);
  if ((r.headers.get('content-type') ?? '').includes('text/html')) return [];
  return parseFootprints(await r.json());
}
